const prefix = ($env.BOT_PREFIX || '/').toString();
const adminsRaw = ($env.BOT_ADMINS || '').toString();
const admins = adminsRaw.split(/[,;\s]+/).map(s => s.trim()).filter(Boolean);

const body = $json.body && typeof $json.body === 'object' ? $json.body : $json;

if (body.typeWebhook && body.typeWebhook !== 'incomingMessageReceived') {
  return [];
}

const messageData = body.messageData || {};
const typeMessage = messageData.typeMessage || '';
let text = '';
if (typeMessage === 'textMessage') {
  text = messageData.textMessageData?.textMessage || '';
} else if (typeMessage === 'extendedTextMessage') {
  text = messageData.extendedTextMessageData?.text || '';
} else {
  return [];
}

text = String(text || '').trim();
if (!text.startsWith(prefix)) {
  return [];
}

const rest = text.slice(prefix.length).trim();
if (!rest) {
  return [];
}

const parts = rest.split(/\s+/);
const command = (parts[0] || '').toLowerCase();
const args = rest.slice(parts[0].length).trim();

const chatId = body.senderData?.chatId || '';
const sender = body.senderData?.sender || chatId;
const isAdmin = admins.length === 0 || admins.includes(sender) || admins.includes(chatId);

const groups = ($env.BROADCAST_GROUPS || '')
  .toString()
  .split(/[,;\s]+/)
  .map(s => s.trim())
  .filter(Boolean);

return [{
  json: {
    command,
    args,
    text,
    prefix,
    chatId,
    sender,
    isAdmin,
    senderName: body.senderData?.senderName || '',
    idMessage: body.idMessage || '',
    groups,
    instanceId: $env.ID_INSTANCE || '',
  }
}];

return [{
  json: {
    chatId: $json.chatId,
    reply: '⛔ Yetkisiz. Bu Ototext komutu sadece admin numaralarına açık.'
  }
}];

const prev = $('Route Command').item.json;
const state = $json.stateInstance || JSON.stringify($json);
return [{
  json: {
    chatId: prev.chatId,
    reply: `📡 Ototext status\ninstance: ${prev.instanceId}\nstate: ${state}`
  }
}];

const prev = $json;
const PAGE_SIZE = 5;
const prefix = prev.prefix || '/';
try {
  const pageArg = (prev.args || '').trim();
  const page = Math.max(1, parseInt(pageArg || '1', 10) || 1);

  const staticData = $getWorkflowStaticData('global');
  staticData.blacklist = Array.isArray(staticData.blacklist) ? staticData.blacklist : [];
  const blacklist = new Set(staticData.blacklist);

  const instance = $env.ID_INSTANCE;
  const token = $env.API_TOKEN;
  if (!instance || !token || instance === 'YOUR_INSTANCE_ID') {
    return [{ json: { chatId: prev.chatId, reply: '⚠️ Green API credential eksik. Mobil kurulum formunu doldur.' } }];
  }
  const base = `https://api.green-api.com/waInstance${instance}`;

  let chats;
  try {
    chats = await this.helpers.httpRequest({
      method: 'GET',
      url: `${base}/getChats/${token}`,
      qs: { count: 500 },
      json: true,
    });
  } catch (e1) {
    // some instances expect POST
    chats = await this.helpers.httpRequest({
      method: 'POST',
      url: `${base}/getChats/${token}`,
      body: { count: 500 },
      json: true,
    });
  }

  const list = Array.isArray(chats) ? chats : [];
  const groups = list
    .filter((c) => c && (c.type === 'group' || String(c.id || '').endsWith('@g.us')))
    .map((c) => ({ id: c.id, name: c.name || c.id }))
    .sort((a, b) => String(a.name).localeCompare(String(b.name), 'tr'));

  const total = groups.length;
  const totalPages = Math.max(1, Math.ceil(total / PAGE_SIZE) || 1);
  const safePage = Math.min(page, totalPages);
  const start = (safePage - 1) * PAGE_SIZE;
  const slice = groups.slice(start, start + PAGE_SIZE);

  const enriched = [];
  for (let i = 0; i < slice.length; i++) {
    const g = slice[i];
    let members = '?';
    let subject = g.name;
    try {
      const data = await this.helpers.httpRequest({
        method: 'POST',
        url: `${base}/getGroupData/${token}`,
        body: { groupId: g.id },
        json: true,
      });
      subject = data.subject || g.name || g.id;
      if (typeof data.size === 'number') members = data.size;
      else if (Array.isArray(data.participants)) members = data.participants.length;
    } catch (e) {}
    enriched.push({
      no: start + i + 1,
      id: g.id,
      name: subject,
      members,
      blocked: blacklist.has(g.id),
    });
  }

  staticData.lastGroupsPage = { page: safePage, totalPages, items: enriched };

  if (!total) {
    return [{ json: { chatId: prev.chatId, reply: '📋 Hiç grup bulunamadı.' } }];
  }

  const lines = [
    `📋 *Gruplar* — sayfa ${safePage}/${totalPages} (toplam ${total})`,
    '',
  ];
  for (const g of enriched) {
    const flag = g.blocked ? ' 🚫' : '';
    lines.push(`${g.no}. ${g.name}${flag}`);
    lines.push(`   👥 ${g.members} üye`);
    lines.push(`   🆔 ${g.id}`);
    lines.push('');
  }
  if (safePage < totalPages) lines.push(`Sonraki: ${prefix}groups ${safePage + 1}`);
  if (safePage > 1) lines.push(`Önceki: ${prefix}groups ${safePage - 1}`);
  lines.push(`Kara liste: ${prefix}blacklist <no|id>`);

  return [{ json: { chatId: prev.chatId, reply: lines.join('\n').trim() } }];
} catch (e) {
  const msg = (e && (e.message || e.description || String(e))) || 'unknown';
  return [{ json: { chatId: prev.chatId, reply: `⚠️ Grup listesi alınamadı.\n${msg}` } }];
}

const msg = ($json.args || '').trim();
const prev = $json;
const staticData = $getWorkflowStaticData('global');
const blacklist = new Set(Array.isArray(staticData.blacklist) ? staticData.blacklist : []);

if (!msg) {
  return [{ json: { chatId: prev.chatId, reply: `Kullanım: ${prev.prefix}broadcast <mesaj>`, skipBroadcast: true } }];
}

let groups = (prev.groups || []).filter(Boolean);

if (!groups.length) {
  // fallback: all groups from WhatsApp account
  const instance = $env.ID_INSTANCE;
  const token = $env.API_TOKEN;
  const chats = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://api.green-api.com/waInstance${instance}/getChats/${token}`,
    qs: { count: 500 },
    json: true,
  });
  groups = (Array.isArray(chats) ? chats : [])
    .filter((c) => c && (c.type === 'group' || String(c.id || '').endsWith('@g.us')))
    .map((c) => c.id);
}

const skipped = groups.filter((g) => blacklist.has(g));
groups = groups.filter((g) => !blacklist.has(g));

if (!groups.length) {
  return [{ json: { chatId: prev.chatId, reply: `Gönderilecek grup yok.\nKara listede: ${skipped.length}`, skipBroadcast: true } }];
}

return groups.map((chatId, index) => ({
  json: {
    index: index + 1,
    total: groups.length,
    skipped: skipped.length,
    targetChatId: chatId,
    message: msg,
    replyChatId: prev.chatId,
    skipBroadcast: false,
  }
}));

const first = $('Broadcast Prepare').first().json;
const total = first.total || 0;
const skipped = first.skipped || 0;
const extra = skipped ? `\n🚫 Kara listede atlandı: ${skipped}` : '';
return [{
  json: {
    chatId: first.replyChatId,
    reply: `✅ Broadcast tamam — ${total} gruba gönderildi.${extra}`
  }
}];

const source = $env.SOURCE_GROUP_ID || '-';
const target = $env.TARGET_GROUP_ID || '-';
return [{
  json: {
    chatId: $json.chatId,
    reply: `🔄 Sync komutu alındı.\nKaynak: ${source}\nHedef: ${target}\n\nNot: Uzun sync için "Ototext — Grup Katılımcı Senkronizasyonu" workflow'unu UI'dan Manual Trigger ile çalıştırın (15 dk rate limit).`,
    runSync: true,
    sourceGroupId: source,
    targetGroupId: target
  }
}];

const p = $json.prefix || '/';
return [{
  json: {
    chatId: $json.chatId,
    reply: `❓ Bilinmeyen komut: ${$json.command}\n${p}help yazarak listeyi görün.`
  }
}];

const prev = $json;
const prefix = prev.prefix || '/';
const arg = (prev.args || '').trim();
const staticData = $getWorkflowStaticData('global');
staticData.blacklist = Array.isArray(staticData.blacklist) ? staticData.blacklist : [];

function resolveId(raw) {
  if (!raw) return null;
  if (raw.includes('@g.us') || raw.includes('@c.us')) return raw;
  const n = parseInt(raw, 10);
  if (!Number.isFinite(n)) return null;
  const page = staticData.lastGroupsPage || {};
  const items = Array.isArray(page.items) ? page.items : [];
  // match absolute no from /groups list
  const byNo = items.find((x) => x.no === n);
  if (byNo) return byNo.id;
  // or 1-based index within last page
  if (n >= 1 && n <= items.length) return items[n - 1].id;
  return null;
}

if (!arg) {
  const bl = staticData.blacklist;
  if (!bl.length) {
    return [{ json: { chatId: prev.chatId, reply: `🚫 Kara liste boş.\nEklemek: ${prefix}blacklist <no|id>\nNo için önce ${prefix}groups` } }];
  }
  const lines = [`🚫 *Kara liste* (${bl.length})`, ''];
  bl.forEach((id, i) => lines.push(`${i + 1}. ${id}`));
  lines.push('', `Çıkar: ${prefix}unblacklist <no|id>`);
  return [{ json: { chatId: prev.chatId, reply: lines.join('\n') } }];
}

const id = resolveId(arg);
if (!id) {
  return [{ json: { chatId: prev.chatId, reply: `Geçersiz hedef: ${arg}\nÖrnek: ${prefix}blacklist 3  veya  ${prefix}blacklist 120363...@g.us\nÖnce ${prefix}groups ile listele.` } }];
}

if (!staticData.blacklist.includes(id)) {
  staticData.blacklist.push(id);
}

return [{ json: { chatId: prev.chatId, reply: `🚫 Kara listeye eklendi.\n${id}\n\nArtık /broadcast bu gruba mesaj atmaz.\nToplam blacklist: ${staticData.blacklist.length}` } }];

const prev = $json;
const prefix = prev.prefix || '/';
const arg = (prev.args || '').trim();
const staticData = $getWorkflowStaticData('global');
staticData.blacklist = Array.isArray(staticData.blacklist) ? staticData.blacklist : [];

function resolveId(raw) {
  if (!raw) return null;
  if (raw.includes('@')) return raw;
  const n = parseInt(raw, 10);
  if (!Number.isFinite(n)) return null;
  // index in blacklist list
  if (n >= 1 && n <= staticData.blacklist.length) return staticData.blacklist[n - 1];
  const page = staticData.lastGroupsPage || {};
  const items = Array.isArray(page.items) ? page.items : [];
  const byNo = items.find((x) => x.no === n);
  if (byNo) return byNo.id;
  if (n >= 1 && n <= items.length) return items[n - 1].id;
  return null;
}

if (!arg) {
  return [{ json: { chatId: prev.chatId, reply: `Kullanım: ${prefix}unblacklist <no|id>` } }];
}

const id = resolveId(arg);
if (!id) {
  return [{ json: { chatId: prev.chatId, reply: `Bulunamadı: ${arg}` } }];
}

const before = staticData.blacklist.length;
staticData.blacklist = staticData.blacklist.filter((x) => x !== id);
const removed = before !== staticData.blacklist.length;
return [{ json: { chatId: prev.chatId, reply: removed ? `✅ Kara listeden çıkarıldı.\n${id}` : `Zaten listede yoktu.\n${id}` } }];
